package com.nbi.errors.service;

import com.nbi.errors.dto.TransferRequest;
import com.nbi.errors.exception.*;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class TransferService {
    private final Map<String, BigDecimal> balances = new HashMap<>();

    public TransferService() {
        balances.put("SAV2001", new BigDecimal("1000000.00")); // Rajesh
        balances.put("CUR3001", new BigDecimal("250000.00"));  // Priya
    }

    public String transfer(TransferRequest r) {
        if (!balances.containsKey(r.from()) || !balances.containsKey(r.to()))
            throw new AccountNotFoundException("One of the accounts does not exist");
        if (balances.get(r.from()).compareTo(r.amount()) < 0)
            throw new InsufficientFundsException("Balance is too low for this transfer");
        if ("CRASH".equals(r.to()))
            throw new RuntimeException("simulated unexpected failure"); // → 500, no stack leak
        balances.put(r.from(), balances.get(r.from()).subtract(r.amount()));
        balances.put(r.to(), balances.get(r.to()).add(r.amount()));
        return "TXF-" + UUID.randomUUID().toString().substring(0, 8);
    }
}
