package com.nbi.errors.exception;

import com.nbi.errors.dto.ApiError;
import org.slf4j.*;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;
import java.util.UUID;

// Central mapping: one place, consistent shape, correct status, no try/catch in controllers.
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(AccountNotFoundException.class)
    public ResponseEntity<ApiError> notFound(AccountNotFoundException e) {
        return build(HttpStatus.NOT_FOUND, "ACCOUNT_NOT_FOUND", e.getMessage(), e);
    }

    @ExceptionHandler(InsufficientFundsException.class)
    public ResponseEntity<ApiError> funds(InsufficientFundsException e) {
        return build(HttpStatus.UNPROCESSABLE_ENTITY, "INSUFFICIENT_FUNDS", e.getMessage(), e);
    }

    // Catch-all: 500, generic message, FULL stack trace to LOGS only (never to client).
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiError> unexpected(Exception e) {
        return build(HttpStatus.INTERNAL_SERVER_ERROR, "INTERNAL_ERROR",
                "An unexpected error occurred", e);
    }

    private ResponseEntity<ApiError> build(HttpStatus status, String code, String msg, Exception e) {
        String traceId = UUID.randomUUID().toString(); // correlation id
        // Stack trace goes to the LOG, keyed by traceId — NOT into the response body.
        log.error("traceId={} code={} status={}", traceId, code, status.value(), e);
        return ResponseEntity.status(status)
                .body(new ApiError(code, msg, traceId, Instant.now()));
    }
}
