package com.nbi.errors.controller;

import com.nbi.errors.dto.TransferRequest;
import com.nbi.errors.service.TransferService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.net.URI;

@RestController
@RequestMapping("/api/v1/transfers")
public class TransferController {

    private final TransferService service;
    public TransferController(TransferService service) { this.service = service; }

    // NO try/catch here — exceptions bubble to the central advice.
    @PostMapping
    public ResponseEntity<String> create(@Valid @RequestBody TransferRequest r) {
        String txId = service.transfer(r);
        return ResponseEntity.created(URI.create("/api/v1/transfers/" + txId)).body(txId);
    }
}
```
